// A3 3.12 rule 2: a generator's notice marks an instruction or configuration file as managed
// elsewhere; a person's own rules about generated files, editing or "this file" do not. The table
// is the rule's specification: each row is a file's first lines and the line of the notice, or
// null for none. The check is best effort (A3 3.12): the rows marked as limits are the errors it
// accepts, with what each costs.
import { describe, expect, test } from "vitest";
import { generatorNotice, NOTICE_CHARS } from "./generated.ts";

type Row = readonly [text: string, line: number | null];

/**
 * Each alternative of the rule: a row only that alternative matches, and a near miss it must
 * not. Dropping or loosening an alternative fails a row here.
 */
const ALTERNATIVES: Readonly<Record<string, readonly Row[]>> = {
  "generated by|from|with|using, after an optional 'code'": [
    ["<!-- Code generated by protoc-gen-docs. DO NOT EDIT. -->\n", 1],
    ["Generated by rules-sync on 2026-01-01\n", 1],
    ["Generated from schema.yaml.\n", 1],
    ["Generated with rules-sync.\n", 1],
    ["Generated using rules-sync.\n", 1],
    ["<!-- Code generation is described in docs/. -->\n", null],
    ["Generated code lives in dist/.\n", null],
    ["Generated bytes are cached.\n", null],
  ],
  "auto-, auto , autogenerated, automatically generated": [
    ["_Auto-generated by rules-sync; do not edit._\n", 1],
    ["<!-- Auto generated by rules-sync -->\n", 1],
    ["<!-- Autogenerated by rules-sync -->\n", 1],
    ["# Rules\n\nThis file was automatically generated by a docs tool.\n", 3],
    ["<!-- Automated by rules-sync -->\n", null],
  ],
  "generated file": [
    ["<!-- AUTO-GENERATED FILE. DO NOT EDIT. -->\n", 1],
    ["<!-- Generated files live in dist/. -->\n", null],
  ],
  "generated, alone": [
    ["<!-- generated -->\n", 1],
    ["# AGENTS.md — generated, do not edit\n", 1],
    ["# Generated code\n", null],
  ],
  "managed by": [
    ["<!-- managed by a dotfiles manager -->\n", 1],
    ["<!-- managed bookmarks -->\n", null],
    ["<!-- Credentials are managed by the OS keychain. -->\n", null],
  ],
  "<tool> managed, alone": [
    ["# Ansible managed\n", 1],
    ["# Ansible managed hosts\n", null],
  ],
  "a bare do not edit|modify, with 'this file', 'manually', 'directly' or 'by hand'": [
    ["DO NOT EDIT\n\n# Rules\n", 1],
    ["<!-- DO NOT MODIFY -->\n", 1],
    // A file that asks plainly not to be edited is honoured: the refusal names print-block.
    ["Do not edit this file.\n\n# Rules\n", 1],
    ["<!-- Do not edit manually. -->\n", 1],
    ["<!-- DO NOT EDIT DIRECTLY -->\n", 1],
    ["<!-- Do not edit by hand -->\n", 1],
    ["Do not edit generated files.\n\n- Keep answers short.\n", null],
    ["<!-- Do not edit: vendor/ is replaced by upgrades. -->\n", null],
  ],
  "@generated, alone": [
    ["@generated\n# Rules\n", 1],
    ["<!-- @generated -->\n", 1],
    ["@generated-files: see docs/\n", null],
  ],
  "this file is|was|will be generated|regenerated|managed|synced|overwritten": [
    ["# Rules\n\nThis file is generated by a rules tool.\n", 3],
    ["# Rules\n\nThis file will be overwritten by rules-sync.\n", 3],
    ["# Rules\n\nThis file is regenerated on every build.\n", 3],
    ["<!-- This file is synced from the team's rules. -->\n", 1],
    // Intended: the file says of itself that it is managed. The person adds the block by hand.
    ["This file is managed by me. Ask before changing it.\n", 1],
    ["<!-- This file is managed by me, by hand. -->\n", 1],
    ["# Rules\n\nThis file holds my own rules. It is not generated.\n", null],
    ["# Rules\n\nThis file is generally short.\n", null],
  ],
  "changes (made) to this file will be lost|overwritten": [
    ["Changes to this file will be lost the next time rules-sync runs.\n", 1],
    ["Changes made to this file will be overwritten.\n", 1],
    ["Changes to this file need a review.\n", null],
  ],
  "this is a|an (auto-)generated file": [
    ["This is an auto-generated file.\n", 1],
    ["This is a generated file.\n", 1],
    ["This is an auto-generated summary of my rules.\n", null],
  ],
  "a sentence's start: after '. ', '! ', '? ' or ': '": [
    ["Note: this file is generated by rules-sync.\n", 1],
    ["# Rules\n\nRead me first. This file is managed by rules-sync.\n", 3],
    ["<!-- DO NOT EDIT: this file is synced from the team's rules -->\n", 1],
    ['<!-- Lint note: rules that say "this file is generated" are checked. -->\n', null],
    ['When reviewing headers, "This file is generated by protoc" means edit the schema.\n', null],
    ["Keep this file short. Read this file before you edit generated code.\n", null],
  ],
  "a title: after '(', ' - ', ': ' or a sentence's end": [
    ["# AGENTS.md (generated by rules-sync)\n", 1],
    ["# AGENTS.md - generated by rules-sync\n", 1],
    ["# AGENTS.md: generated by rules-sync\n", 1],
    ["Team rules. Generated by rules-sync.\n", 1],
    ["# Rules\n\nInstructions — do not edit generated snapshots.\n", null],
    ["# Rules\n\nOur rules: generated by rules-sync.\n", null],
  ],
  "a later heading that names a file": [
    ["# Rules\n\n## AGENTS.md — generated by rules-sync\n", 3],
    ["# Rules\n\n## Snapshots — do not edit\n", null],
  ],
  "spaces and dashes are made plain before matching": [
    ["<!-- Auto  generated by rules-sync -->\n", 1],
    ["<!-- AUTO‑GENERATED FILE -->\n", 1],
    ["<!-- Auto–generated by rules-sync -->\n", 1],
    ["<!-- Auto generated by rules-sync -->\n", 1],
  ],
};

/** A person's own instruction files: setup may add its block to these. */
const PERSON: readonly string[] = [
  "# My rules\n\n- Never edit generated files.\n- Do not edit the lock file.\n",
  "# My rules\n\n- Ask before you edit generated code. Do not edit vendored files.\n",
  "# My rules\n\nDo not edit generated code without reading this file.\n",
  "Never edit files generated by the build.\n",
  "# Rules\n\nGenerated files live in dist/; never edit them.\n",
  "# Rules\n\n- Snapshots: do not edit them by hand.\n- Lockfile: generated by pnpm, never edit it.\n",
  "- Snapshots: do not edit.\n- Fixtures — generated by the seed script.\n",
  "<!-- a note -->\n# Rules\n- regenerate the docs after editing\n",
  "<!-- markdownlint-disable MD013 -->\n# Rules\n",
  "# Rules\n\n<!-- keep this list short; do not edit generated files in work repositories -->\n",
  "# Rules for generated code\n\n- Change the generator, not its output.\n",
  "# Notes\n\n**Generated code:** never edit it.\n",
  "- Do not edit this file without asking me.\n",
  "# Managing my rules\n\nI manage this file by hand, and I keep it in my dotfiles.\n",
  "# Rules\n\nWhen a file says it is generated, do not edit it: change its source.\n",
  // A comment whose subject is another path or thing.
  "# Rules\n\n<!-- dist/: generated by the build. Edit src/ instead. -->\n",
  "# Rules\n\n<!-- Lockfile: do not edit. Run pnpm install. -->\n",
  // Examples: a fenced code block, a block quote and a list item are never a notice.
  "# Rules\n\nExample header:\n\n```\nCode generated by protoc. DO NOT EDIT.\n```\n",
  "# Rules\n\n~~~markdown\n<!-- Generated by documentation-tool -->\n~~~\n",
  "# Rules\n\nExample headers:\n\n- This file is generated by protoc.\n",
  "# Rules\n\n> Example: This file is generated by a script.\n",
  "# Rules\n\n- If this file is generated in a fixture, test the header too.\n",
  "# Rules\n\n- An example header:\n\n  This file is generated by protoc.\n",
  "````\n```\n<!-- generated -->\n```\n````\n",
  // A limit (A3 3.12): a real notice in a block quote is missed, so a later run of its tool
  // removes the block, which doctor reports.
  "# Team rules\n\n> Generated by rules-sync from the team repository. Do not edit.\n",
  "# Rules\n\n> **Note:** This file is managed by the team's skills installer.\n",
  // Past the 20 lines read.
  `${"- a rule\n".repeat(19)}\nThis file is generated by a rules tool.\n`,
];

/** Generators' notices in the forms common tools write, and the line each starts on. */
const GENERATED: readonly Row[] = [
  ["# Rules\n\n<!--\n  This file is generated by a rules tool.\n-->\n", 3],
  ["\n# Generated by a rules tool\n\n- a rule\n", 2],
  ["# Rules\n## Instructions <!-- Generated by rules-sync; do not edit -->\n", 2],
  ["# Rules <!--\n  generated by rules-sync\n-->\n", 1],
  ["# Rules\r\n<!-- Generated by rules-sync -->\r\n", 2],
  ["<!-- generated by rules-sync\n", 1],
  // A notice after a closed fence counts.
  ["```\ncode\n```\n<!-- generated by rules-sync -->\n", 4],
  // A list ends at a line that is not indented.
  ["- a rule\n\nThis file is generated by a rules tool.\n", 3],
  [`${"- a rule\n".repeat(18)}\nThis file is generated by a rules tool.\n`, 20],
];

/** Codex's configuration file: a notice is a comment that is a whole line. */
const TOML: readonly Row[] = [
  ['# Generated by a dotfiles tool. Do not edit.\nmodel = "x"\n', 1],
  ['model = "x"\n# managed by a dotfiles manager\n', 2],
  ["# DO NOT EDIT\n", 1],
  ["# @generated\n", 1],
  ['# This file is managed by a provisioning tool.\nmodel = "x"\n', 1],
  ['# Do not edit generated profiles below by hand\nmodel = "x"\n', null],
  ['# my settings\nmodel = "generated"\n', null],
  ['# Credentials are managed by the OS keychain.\nmodel = "x"\n', null],
  ['model = "x" # generated by a dotfiles tool\n', null],
  // A `#` line inside a multi-line string is the string's text, not a comment.
  ['notes = """\n# Generated by a dotfiles tool. Do not edit.\n"""\n', null],
  ["notes = '''\n# DO NOT EDIT\n'''\n", null],
  ['notes = """\n# Generated by a dotfiles tool.""" # a note\n', null],
  // A comment line inside an array spread over lines is a comment.
  ['args = [\n  # generated by a dotfiles tool\n  "x",\n]\n', 2],
];

describe("[A3.3.12.setup.generated] rule 2: a generator's notice, not a person's rule", () => {
  for (const [name, rows] of Object.entries(ALTERNATIVES)) {
    test.each(rows)(`${name}: %j`, (text, line) => {
      expect(generatorNotice(text, "markdown")).toBe(line ?? undefined);
    });
  }

  test.each(PERSON)("not a notice: %j", (text) => {
    expect(generatorNotice(text, "markdown")).toBeUndefined();
  });

  test.each(GENERATED)("a generator's notice marks the file: %j", (text, line) => {
    expect(generatorNotice(text, "markdown")).toBe(line);
  });

  test.each(TOML)("TOML: %j", (text, line) => {
    expect(generatorNotice(text, "toml")).toBe(line ?? undefined);
  });

  test("text cut at the bound is never a notice: a cut can leave a phrase that only looks whole", () => {
    // Each line's first NOTICE_CHARS characters end in "do not edit", a bare prohibition.
    const cut = (start: string): string =>
      `${start}${" ".repeat(NOTICE_CHARS - start.length - 11)}do not edit generated files\n`;
    expect(generatorNotice(cut(""), "markdown")).toBeUndefined();
    expect(generatorNotice(cut("#"), "toml")).toBeUndefined();
    expect(generatorNotice(`${cut("<!--")}-->\n`, "markdown")).toBeUndefined();
    // A comment that closes within the bound is whole, whatever follows it on the line.
    expect(
      generatorNotice(`<!-- generated by rules-sync -->${"x".repeat(NOTICE_CHARS)}\n`, "markdown"),
    ).toBe(1);
  });

  test("only the start of each line is read, so a long line costs no more than a short one", () => {
    // A pasted blob near the top: each would take minutes if every position were tried in full.
    const long = [
      `<!-- ${"a.".repeat(1_000_000)}`,
      `# ${"a.".repeat(1_000_000)}`,
      `# t ${"*".repeat(2_000_000)}`,
      `<!-- generated by rules-sync ${"a.".repeat(1_000_000)}`,
      // A comment that opens past the part of the line that is read is not a notice.
      `${"x".repeat(NOTICE_CHARS)} <!-- generated by rules-sync -->\n`,
    ];
    for (const text of long) {
      expect(generatorNotice(text, "markdown")).toBeUndefined();
      expect(generatorNotice(text, "toml")).toBeUndefined();
    }
  });
});
